def build(lang,prefix):
 t=DATA[lang];other='es' if lang=='en' else 'en';a=prefix+'assets/';ar='<span class="arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 19 19 5M5 5h14v14"/></svg></span>'
